	/** 
	 * jumpstart the process by instantiating2 Asset
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		assetId = AssetService.getAssetInstance()
		.createAsset( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AssetService.getAssetInstance()
				.createAsset( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.assetSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Asset : " + successValue.getAssetId());
							  if (successValue.getAssetId().equals(assetId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAssetList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Asset test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on asset consumed")
					);
			subscriber.assetSubscribe( assetId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Asset : " + successValue.getAssetId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAssetList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on asset for assetId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Asset. 
	 */
	protected Asset read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Asset" );

		Asset entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Asset with primary key" );
		msg.append( assetId );
		
		AssetFetchOneSummary fetchOneSummary = new AssetFetchOneSummary( assetId );

		try {
			entity = AssetService.getAssetInstance().getAsset( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Asset " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Asset.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Asset." );

		StringBuilder msg = new StringBuilder( "Failed to update a Asset : " );        
		Asset entity = read();
		UpdateAssetCommand command = generateUpdateCommand();
		command.setAssetId(entity.getAssetId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Asset." );

			// for use later on...
			assetId = entity.getAssetId();

			AssetService proxy = AssetService.getAssetInstance();  

			proxy.updateAsset( command ).get();

			LOGGER.info( "-- Successfully saved Asset - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + assetId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Asset.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Asset." );

		Asset entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Asset with id " + assetId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Asset with id " + assetId );

			throw e;
		}

		try{
			AssetService.getAssetInstance().delete( new DeleteAssetCommand( entity.getAssetId() ) ).get();
			LOGGER.info( "-- Successfully deleted Asset with id " + assetId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Asset with id " + assetId );

			throw e;
		}
	}

	/**
	 * get all Assets.
	 */
	protected List<Asset> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Assets:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Asset : " );        
		List<Asset> collection  = new ArrayList<>();

		try {
			// call the static get method on the AssetService
			collection = AssetService.getAssetInstance().getAllAsset();
			assertNotNull( collection, "An Empty collection of Asset was incorrectly returned.");
			
			// Now print out the values
			Asset entity = null;            
			Iterator<Asset> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAssetId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

